import fs from 'fs';

// Fix [...slug]/page.tsx - has <div> wrapper with \\r\\n line endings
const slugFile = 'c:/dev/lhermitage/app/[...slug]/page.tsx';
let content1 = fs.readFileSync\(slugFile, 'utf-8'\);

// Step 1: Remove opening <div> wrapper before PageHeader
content1 = content1.replace\(/\(\\r?\\n\)\([ \\t]*\)<div>\\s*\\r?\\n\([ \\t]*<PageHeader\)/g, '$1$3'\);

// Step 2: Change self-closing /> on PageHeader to >
const lines1 = content1.split\('\\n'\);
let inPH1 = false;
for \(let i = 0; i < lines1.length; i++\) {
    if \(lines1[i].includes\('<PageHeader'\)\) {
        inPH1 = true;
    }
    if \(inPH1 && lines1[i].match\(/\\/>\\s*\\r?$/\)\) {
        lines1[i] = lines1[i].replace\(/\\/>\\s*\\r?$/, '>'\);
        // Preserve \\r if it was there
        inPH1 = false;
    }
}
content1 = lines1.join\('\\n'\);

// Step 3: Replace the LAST </div> with </PageHeader>
const lastDivIdx1 = content1.lastIndexOf\('</div>'\);
if \(lastDivIdx1 !== -1\) {
    content1 = content1.substring\(0, lastDivIdx1\) + '</PageHeader>' + content1.substring\(lastDivIdx1 + '</div>'.length\);
}

fs.writeFileSync\(slugFile, content1, 'utf-8'\);
console.log\('Fixed: ' + slugFile\);

// Fix activite/[slug]/page.tsx - has <> fragment wrapper
const activiteFile = 'c:/dev/lhermitage/app/activite/[slug]/page.tsx';
let content2 = fs.readFileSync\(activiteFile, 'utf-8'\);

// Step 1: Remove opening <> fragment before PageHeader
content2 = content2.replace\(/\(\\r?\\n\)\([ \\t]*\)<>\\s*\\r?\\n\([ \\t]*<PageHeader\)/g, '$1$3'\);

// Step 2: Change self-closing /> on PageHeader to >
const lines2 = content2.split\('\\n'\);
let inPH2 = false;
for \(let i = 0; i < lines2.length; i++\) {
    if \(lines2[i].includes\('<PageHeader'\)\) {
        inPH2 = true;
    }
    if \(inPH2 && lines2[i].match\(/\\/>\\s*\\r?$/\)\) {
        lines2[i] = lines2[i].replace\(/\\/>\\s*\\r?$/, '>'\);
        inPH2 = false;
    }
}
content2 = lines2.join\('\\n'\);

// Step 3: Replace the LAST </> with </PageHeader>
const lastFragIdx = content2.lastIndexOf\('</>'\);
if \(lastFragIdx !== -1\) {
    content2 = content2.substring\(0, lastFragIdx\) + '</PageHeader>' + content2.substring\(lastFragIdx + '</>'.length\);
}

fs.writeFileSync\(activiteFile, content2, 'utf-8'\);
console.log\('Fixed: ' + activiteFile\);

console.log\('Done.'\);
